import{_ as d,a0 as i,w as l,s as p,ao as s,I as r,x as a,a1 as e,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const I=JSON.parse('{"title":"我的 Android 開發者之路以及我在其中學到了什麼 | LCTT x X-CMD","titleTemplate":false,"description":"我的 Android 開發者之路以及我在其中學到了什麼 | LCTT (201609) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"我的 Android 開發者之路以及我在其中學到了什麼 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"我的 Android 開發者之路以及我在其中學到了什麼 | LCTT (201609) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201609/20160814 How I Got to be an Android Dev And What I Learned From It","title":"我的 Android 開發者之路以及我在其中學到了什麼","tag":"201609","desc":""},"relativePath":"201609/20160814 How I Got to be an Android Dev And What I Learned From It.md","filePath":"[post].md"}'),m={name:"201609/20160814 How I Got to be an Android Dev And What I Learned From It.md"};function h(u,t,f,T,A,g){const o=i("Link");return l(),p("div",null,[t[13]||(t[13]=s('<h1 id="我的-android-開發者之路以及我在其中學到了什麼" tabindex="-1">我的 Android 開發者之路以及我在其中學到了什麼 <a class="header-anchor" href="#我的-android-開發者之路以及我在其中學到了什麼" aria-label="Permalink to “我的 Android 開發者之路以及我在其中學到了什麼”">​</a></h1><p>大家都説所有的關係都需要經歷兩年、七年甚至十年的磨礪。我忘了是誰説的這句話，但肯定有人在幾年前這麼跟我説過。</p><p>下週是我來悉尼兩週年，所以我想現在正是我寫這篇文章的好時候。</p><p>去年五月份參加 I/O 年會的時候，我遇到了亞斯曼女士，她十分漂亮。她向我詢問我是如何成長為一名安卓開發者的，當我説完我的經歷時，她認為我應該寫個Blog記下來。所以亞斯曼，如你所願，雖然遲了點，但好過沒做。😉</p><h3 id="故事的開始" tabindex="-1">故事的開始 <a class="header-anchor" href="#故事的開始" aria-label="Permalink to “故事的開始”">​</a></h3><p>如果有件事我可能希望你知道，那就是我發現自己有選擇困難症。你最好的朋友是誰？你最喜歡的食物是什麼？你應該給你的玩具熊貓命名嗎？我連這些問題都不知道該怎麼回答才好。所以你可以想像到，16 歲的、即將高中畢業的我對於專業選擇根本就沒有任何想法。那我最初申請的大學是？在交表給註冊員前，我在她面前逐字掂量着寫下這個打算申請的專業（商業經濟學）。</p><p>可我最後去了另外一間學校，就讀電子與通信工程。大一時我有一門計算機編程課程。但我很討厭編程，十分地討厭。關於編程的一切我都一無所知。我曾發誓再也不要寫代碼了。</p><p>我大學畢業後的第一份工作是在英特爾做產品工程師並在那呆了兩年。我很迷茫，無所適從，整天長時間工作。這在我意料之中，身為成年人難道不該努力工作嗎？可之後菲律賓的半導體行業開始呈現頹勢，大批工廠紛紛倒閉，以前由我們維護一些產品被轉移到其他分公司。我便決定去找另一份工作而不是等着被裁員，因為被裁員後我都不知道自己多久才能找到另一份工作。</p><h3 id="現在呢" tabindex="-1">現在呢？ <a class="header-anchor" href="#現在呢" aria-label="Permalink to “現在呢？”">​</a></h3><p>我想留在城市裏找到一份工作，但我不想呆在正在沒落的半導體行業裏了。但話説回來，我又不知道該做什麼好。對了，我可是拿了畢業證書的工程師，所以從技術上來説我可以在電信運營商或電視台找到工作。可這種時候，如果想入職電信運營商，我應該在大學畢業之際就去他們那實習，這樣更容易被錄用。可惜我沒有，所以我放棄了這個想法。雖然有很多軟件開發人員的招聘信息，但我討厭編程，所以我真的不知道怎麼做才好。</p><p>接下來是我第一個幸運的機遇，我很幸運地遇到了信任我的上司，我也和她坦誠了我什麼都不會。之後我不得不邊工作邊學習，一開始這個過程很漫長。無需多言，我在這份工作上學到了很多，也結識了很多很好的人，與我一起的是一羣很厲害的同事（我們曾開發出安裝在 SIM 卡上的 APP）。但更重要的是我開始踏上了軟件開發的征途。</p><p>最後我做得更多是一些公司的瑣事（十分無聊）直到項目完結。換句話説，我總在是在辦公室裏閒逛並坐等發薪。之後我發現這確實是在浪費時間，2009 年的時候，我不停地接觸到關於谷歌的新系統 Android 的消息，並得知它的 SDK 已經公佈！是時候嘗試一波了。於是我安裝了所有相關軟件並着手 Android 開發。</p><h3 id="事情變得有趣了" tabindex="-1">事情變得有趣了 <a class="header-anchor" href="#事情變得有趣了" aria-label="Permalink to “事情變得有趣了”">​</a></h3><p>所以現在我能夠構建一個在運行在仿真器的 Hello World 應用，在我看來意味着我有勝任安卓開發工作的能力。我加入了一個創業公司，並且再次坦誠我不知道該怎麼做，我只是接觸過一些；但如果你們願意付薪水給我繼續嘗試，我們就可以成為朋友。然後我很幸運地遇到另一個機遇。</p><p>那時成為開發者是一件令人欣喜的事。StackOverflow 上的 Android 開發社區非常小，我們都在相互交流學習，説真的，我認為裏面的所有人都很友好、很豪邁（注 1）！</p><p>我最後去了一家企業，這家企業的移動開發團隊在馬尼拉、悉尼、紐約都設有辦公地點。而我是馬尼拉辦公地點的第一個安卓開發人員，但那時我很習慣，並沒有在意。</p><p>在那裏我認識了最後令我永遠感激的引薦我參與 Domain 項目的人。Domain 項目不管在個人或職業上對我來説都意味深重。我和一支很有才華的團隊一起共事，也從沒見過一個公司能如此執着於一款產品。Domain 讓我實現了參加 I/O 年會的夢。與他們共事後我懂得了很多之前沒想到的可愛特性（注 2）。這是又一個幸運的機遇，我是説最大限度地利用它。</p><h3 id="然後呢" tabindex="-1">然後呢？ <a class="header-anchor" href="#然後呢" aria-label="Permalink to “然後呢？”">​</a></h3><p>我想説的是，雖然這些年都在晃盪，但至少我很誠實，對吧？如上就是我所學到的全部東西。説一句「我不懂」沒什麼可怕的。有時候我們是該裝懂，但更多時候我們需要坦誠地接受這樣一個事實：我們還不懂。</p><p>別害怕嘗試新事物，不管它讓你感覺多害怕。我知道説比做簡單。但總有一些東西能讓你鼓起勇氣動手去嘗試的（注3）。Lundagin mo, baby!（LCTT 譯註：一首歌名）</p><p>注 1： 我翻閲着以前在 StackOverflow 提的問題，認真想想，如果現在我問他們這些，估計會收到很多「你是誰啊，傻瓜」的評論。我不知道是不是因為我老了，而且有些憤世妒俗。但關鍵是，我們有緣在同一個社區中，所以大家相互之間友善些，好嗎？ 注 2： 這一點寫在另一篇文章裏了。 注 3： 我還清晰地記得第一次申請 Android 開發職位的情形：我寫完求職信後又通讀了一遍，提交前鼠標在發送按鈕上不斷徘徊，深呼吸之後我趁改變主意之前把它發出去了。</p><hr>',22)),r("p",null,[t[1]||(t[1]=a("via: ",-1)),e(o,{href:"http://www.zdominguez.com/2016/08/winging-it-how-i-got-to-be-android-dev.html"},{default:n(()=>[...t[0]||(t[0]=[a("http://www.zdominguez.com/2016/08/winging-it-how-i-got-to-be-android-dev.html",-1)])]),_:1})]),r("p",null,[t[5]||(t[5]=a("作者：",-1)),e(o,{href:"https://plus.google.com/102371834744366149197"},{default:n(()=>[...t[2]||(t[2]=[a("Zarah Dominguez",-1)])]),_:1}),t[6]||(t[6]=a(" 譯者：",-1)),e(o,{href:"https://github.com/JianhuanZhuo"},{default:n(()=>[...t[3]||(t[3]=[a("JianhuanZhuo",-1)])]),_:1}),t[7]||(t[7]=a(" 校對：",-1)),e(o,{href:"https://github.com/PurlingNayuki"},{default:n(()=>[...t[4]||(t[4]=[a("PurlingNayuki",-1)])]),_:1})]),r("p",null,[t[10]||(t[10]=a("本文由 ",-1)),e(o,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[8]||(t[8]=[a("LCTT",-1)])]),_:1}),t[11]||(t[11]=a(" 原創編譯，",-1)),e(o,{href:"https://linux.cn/"},{default:n(()=>[...t[9]||(t[9]=[a("Linux中國",-1)])]),_:1}),t[12]||(t[12]=a(" 榮譽推出",-1))])])}const _=d(m,[["render",h]]);export{I as __pageData,_ as default};
